async function PERFORM(a_, o = false, i = false) {
  let v_ = false, oa = 0, oo = 0, oi = 0;
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  g.PRSA = a_;
  if (!g.LIT && (await SEE_VERB$())) {
    await TOO_DARK();
    return M_FATAL;
  } else if (g.IMMOBILIZED$ && !(await SEE_VERB$()) && !(await GAME_VERB$()) && !(g.PRSA == V.AGAIN)) {
    tell("Your body seems unwilling to respond.\n");
    return M_FATAL;
  } else if (!(a_ == V.WALK)) {
    if ((IT == i || IT == o) && !(await ACCESSIBLE$(g.P_IT_OBJECT))) {
      if (!i) {
        await FAKE_ORPHAN();
      } else {
        await CANT_SEE_ANY(g.P_IT_OBJECT);
      }
      return M_FATAL;
    }
    if (THEM == i || THEM == o) {
      if (await VISIBLE$(g.P_THEM_OBJECT)) {
        if (THEM == o) {
          o = g.P_THEM_OBJECT;
        }
        if (THEM == i) {
          i = g.P_THEM_OBJECT;
        }
      } else {
        if (!i) {
          await FAKE_ORPHAN();
        } else {
          await CANT_SEE_ANY(g.P_THEM_OBJECT);
        }
        return M_FATAL;
      }
    }
    if (HER == i || HER == o) {
      if (await VISIBLE$(g.P_HER_OBJECT)) {
        if (HER == o) {
          o = g.P_HER_OBJECT;
        }
        if (HER == i) {
          i = g.P_HER_OBJECT;
        }
      } else {
        if (!i) {
          await FAKE_ORPHAN();
        } else {
          await CANT_SEE_ANY(g.P_HER_OBJECT);
        }
        return M_FATAL;
      }
    }
    if (HIM == i || HIM == o) {
      if (await VISIBLE$(g.P_HIM_OBJECT)) {
        if (HIM == o) {
          o = g.P_HIM_OBJECT;
        }
        if (HIM == i) {
          i = g.P_HIM_OBJECT;
        }
      } else {
        if (!i) {
          await FAKE_ORPHAN();
        } else {
          await CANT_SEE_ANY(g.P_HIM_OBJECT);
        }
        return M_FATAL;
      }
    }
    if (o == IT) {
      o = g.P_IT_OBJECT;
    }
    if (i == IT) {
      i = g.P_IT_OBJECT;
    }
  }
  g.PRSI = i;
  g.PRSO = o;
  v_ = false;
  if (!(a_ == V.WALK) && (NOT_HERE_OBJECT == g.PRSO || NOT_HERE_OBJECT == g.PRSI)) {
    v_ = await apply(NOT_HERE_OBJECT_F.id);
    if (v_) {
      g.P_WON = false;
    }
  }
  await THIS_IS_IT(g.PRSI);
  await THIS_IS_IT(g.PRSO);
  o = g.PRSO;
  i = g.PRSI;
  if (v_ == 0) {
    v_ = await apply(getProp(g.WINNER, P.ACTION), M_WINNER);
  }
  if (v_ == 0) {
    v_ = await apply(getProp(loc(g.WINNER), P.ACTION), M_BEG);
  }
  if (v_ == 0) {
    v_ = await apply(get(g.PREACTIONS, a_));
  }
  if ((v_ == 0) && !(g.WINNER == PROTAGONIST)) {
    await apply(get(g.ACTIONS, a_));
    v_ = true;
  }
  if ((v_ == 0) && i && !(a_ == V.WALK) && loc(i)) {
    v_ = getProp(loc(i), P.CONTFCN);
    if (v_) {
      v_ = await apply(v_, M_CONT);
    }
  }
  if ((v_ == 0) && i) {
    v_ = await apply(getProp(i, P.ACTION));
  }
  if ((v_ == 0) && o && !(a_ == V.WALK) && loc(o)) {
    v_ = getProp(loc(o), P.CONTFCN);
    if (v_) {
      v_ = await apply(v_, M_CONT);
    }
  }
  if ((v_ == 0) && o && !(a_ == V.WALK)) {
    v_ = await apply(getProp(o, P.ACTION));
    if (v_) {
      await THIS_IS_IT(o);
    }
  }
  if (v_ == 0) {
    v_ = await apply(get(g.ACTIONS, a_));
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

async function BUZZER_WORD$(word) {
  if (await QUESTION_WORD$(word)) {
    return true;
  } else if (await NAUGHTY_WORD$(word)) {
    return true;
  } else if (await MAGIC_WORD$(word)) {
    return true;
  } else if ((word == W.NW || word == W.NORTHW || word == W.NE) || (word == W.SW || word == W.SOUTHW || word == W.NORTHE) || (word == W.SE || word == W.SOUTHE)) {
    await V_BAD_DIRECTION();
    return true;
  } else if (word == W.MOUSE || word == W.RAT || word == W.RODENT) {
    if ((g.HERE == INSIDE_CHURCH) && !(hasFlag(CHURCH, TOUCHBIT))) {
      tell("It disappeared before you could get a good look.\n");
    } else {
      await CANT_SEE_ANY();
    }
    return true;
  } else if (await SESAME$(word)) {
    return true;
  } else if ((word == W.FUZZY || word == W.BLURRY || word == W.BLURRED) && !g.FUZZY$) {
    tell(S(g.YOU_SEE), "nothing ");
    printB(word);
    tell(" here!\n");
    return true;
  } else if (word == W.CORKY) {
    if (loc(CRISP) == g.HERE) {
      tell(D(CRISP), " reddens. \"Don't use that name in front of me!\"");
    } else {
      tell("(", D(CRISP), " hates it when you use that name!)");
    }
    crlf();
    return true;
  } else {
    return false;
  }
}

async function SESAME$(word) {
  let mword = 0;
  if (word == W.KALUZE || word == W.FRATTO || word == W.SORKIN) {
    if (g.POWER == 0) {
      mword = W.KALUZE;
    } else if (g.POWER == 1) {
      mword = W.FRATTO;
    } else {
      mword = W.SORKIN;
    }
    if (!g.SKEWED$ || !(g.HERE == HILLTOP) || !(word == mword)) {
      tell("(The word \"");
      printB(word);
      tell("\" isn't useful here.)\n");
    } else if (hasFlag(PELICAN, RMUNGBIT)) {
      await SAY_THE(DRAWBRIDGE);
      tell(" decides that you're only guessing the word \"");
      printB(word);
      tell(",\" and refuses to cooperate.\n");
    } else if (hasFlag(DRAWBRIDGE, RMUNGBIT)) {
      await NOTHING_EXCITING();
    } else if (g.ECLIPSE$) {
      await DARK_IS_POWERFUL();
    } else {
      setFlag(DRAWBRIDGE, RMUNGBIT);
      setFlag(DRAWBRIDGE, OPENBIT);
      tell("With a great creak of wood and rattle of chains, the ", D(DRAWBRIDGE), " slowly lowers across the moat.\n\n");
      await UPDATE_SCORE(3);
      await GOOD_PLACE_TO_SAVE();
    }
    return true;
  } else {
    return false;
  }
}

