async function BUT_MERGE(tbl) {
  let len = 0, butlen = 0, cnt = 1, matches = 0, obj = 0, ntbl = 0;
  len = get(tbl, g.P_MATCHLEN);
  put(g.P_MERGE, g.P_MATCHLEN, 0);
  loop1: for (;;) {
    if (--len < 0) {
      break loop1;
    } else if (await ZMEMQ(obj = get(tbl, cnt), g.P_BUTS)) {
    } else {
      put(g.P_MERGE, matches + 1, obj);
      matches = matches + 1;
    }
    cnt = cnt + 1;
  }
  put(g.P_MERGE, g.P_MATCHLEN, matches);
  ntbl = g.P_MERGE;
  g.P_MERGE = tbl;
  return ntbl;
}

async function SNARFEM(ptr, eptr, tbl) {
  let but = false, len = 0, wv = 0, wrd = 0, nw = 0, was_all$ = false;
  let $1, $2, $3, $4;
  g.P_AND = false;
  if (g.P_GETFLAGS == P_ALL) {
    was_all$ = true;
  }
  g.P_GETFLAGS = 0;
  put(g.P_BUTS, g.P_MATCHLEN, 0);
  put(tbl, g.P_MATCHLEN, 0);
  wrd = get(ptr, 0);
  for (;;) {
    if (ptr == eptr) {
      wv = await GET_OBJECT(but || tbl);
      if (was_all$) {
        g.P_GETFLAGS = P_ALL;
      }
      return wv;
    } else {
      nw = get(ptr, P_LEXELEN);
      if (wrd == W.ALL || wrd == W.BOTH || wrd == W.EVERYTHING) {
        g.P_GETFLAGS = P_ALL;
        if (nw == W.OF) {
          ptr = ptr + P_WORDLEN;
        }
      } else if (wrd == W.BUT || wrd == W.EXCEPT) {
        $1 = await GET_OBJECT(but || tbl);
        if (!$1) {
          return false;
        }
        but = g.P_BUTS;
        put(but, g.P_MATCHLEN, 0);
      } else if (await BUZZER_WORD$(wrd)) {
        return false;
      } else if (wrd == W.A) {
        if (!g.P_ADJ) {
          g.P_GETFLAGS = P_ONE;
          if (nw == W.OF) {
            ptr = ptr + P_WORDLEN;
          }
        } else {
          g.P_NAM = g.P_ONEOBJ;
          $2 = await GET_OBJECT(but || tbl);
          if (!$2) {
            return false;
          }
          $3 = nw == 0;
          if ($3) {
            return true;
          }
        }
      } else if ((wrd == W.AND || wrd == W.COMMA) && !(nw == W.AND || nw == W.COMMA)) {
        g.P_AND = true;
        $4 = await GET_OBJECT(but || tbl);
        if (!$4) {
          return false;
        }
      } else if (await WT$(wrd, PS$BUZZ_WORD)) {
      } else if (wrd == W.AND || wrd == W.COMMA) {
      } else if (wrd == W.OF) {
        if (g.P_GETFLAGS == 0) {
          g.P_GETFLAGS = P_INHIBIT;
        }
      } else if ((wv = await WT$(wrd, PS$ADJECTIVE, P1$ADJECTIVE)) && !g.P_ADJ) {
        g.P_ADJ = wv;
        g.P_ADJN = wrd;
      } else if (await WT$(wrd, PS$OBJECT, P1$OBJECT)) {
        g.P_NAM = wrd;
        g.P_ONEOBJ = wrd;
      }
    }
    if (!(ptr == eptr)) {
      ptr = ptr + P_WORDLEN;
      wrd = nw;
    }
  }
}

async function GET_OBJECT(tbl, vrb = true) {
  let bts = 0, len = 0, xbits = 0, tlen = 0, gcheck = false, olen = 0, obj = 0, adj = 0, x = 0;
  xbits = g.P_SLOCBITS;
  tlen = get(tbl, g.P_MATCHLEN);
  if (btst(g.P_GETFLAGS, P_INHIBIT)) {
    return true;
  }
  adj = g.P_ADJN;
  if (!g.P_NAM && g.P_ADJ) {
    if (await WT$(g.P_ADJN, PS$OBJECT, P1$OBJECT)) {
      g.P_NAM = g.P_ADJN;
      g.P_ADJ = false;
    } else if (bts = await WT$(g.P_ADJN, PS$DIRECTION, P1$DIRECTION)) {
      g.P_ADJ = false;
      put(tbl, g.P_MATCHLEN, 1);
      put(tbl, 1, INTDIR);
      g.P_DIRECTION = bts;
      return true;
    }
  }
  if (!g.P_NAM && !g.P_ADJ && !(g.P_GETFLAGS == P_ALL) && (g.P_GWIMBIT == 0)) {
    if (vrb) {
      (await NOT_IN_SENTENCE("enough nouns"));
    }
    return false;
  }
  if (!(g.P_GETFLAGS == P_ALL) || (g.P_SLOCBITS == 0)) {
    g.P_SLOCBITS = -1;
  }
  g.P_TABLE = tbl;
  loop1: for (;;) {
    if (gcheck) {
      await GLOBAL_CHECK(tbl);
    } else {
      if (g.LIT) {
        clearFlag(PROTAGONIST, TRANSBIT);
        await DO_SL(g.HERE, SOG, SIR);
        setFlag(PROTAGONIST, TRANSBIT);
      }
      await DO_SL(PROTAGONIST, SH, SC);
    }
    len = get(tbl, g.P_MATCHLEN) - tlen;
    if (btst(g.P_GETFLAGS, P_ALL)) {
    } else if (btst(g.P_GETFLAGS, P_ONE) && !(len == 0)) {
      if (!(len == 1)) {
        put(tbl, 1, get(tbl, random(len)));
        tell("(How about ");
        await ARTICLE(get(tbl, 1), true);
        tell(D(get(tbl, 1)), "?)\n");
      }
      put(tbl, g.P_MATCHLEN, 1);
    } else if ((len > 1) || ((len == 0) && !(g.P_SLOCBITS == (-1)))) {
      if (g.P_SLOCBITS == (-1)) {
        g.P_SLOCBITS = xbits;
        olen = len;
        put(tbl, g.P_MATCHLEN, get(tbl, g.P_MATCHLEN) - len);
        continue loop1;
      } else {
        if (len == 0) {
          len = olen;
        }
        if (!(g.WINNER == PROTAGONIST)) {
          tell("(Please try saying that another way.)\n");
          return false;
        } else if (vrb && g.P_NAM) {
          await WHICH_PRINT(tlen, len, tbl);
          g.P_ACLAUSE = tbl == g.P_PRSO ? P_NC1 : P_NC2;
          g.P_AADJ = g.P_ADJ;
          g.P_ANAM = g.P_NAM;
          await ORPHAN(false, false);
          g.P_OFLAG = true;
        } else if (vrb) {
          (await NOT_IN_SENTENCE("enough nouns"));
        }
        g.P_NAM = false;
        g.P_ADJ = false;
        return false;
      }
    } else if ((len == 0) && gcheck) {
      if (vrb) {
        g.P_SLOCBITS = xbits;
        if (g.LIT || (await SPEAKING_VERB$())) {
          await OBJ_FOUND(NOT_HERE_OBJECT, tbl);
          g.P_XNAM = g.P_NAM;
          g.P_XADJ = g.P_ADJ;
          g.P_XADJN = g.P_ADJN;
          g.P_NAM = false;
          g.P_ADJ = false;
          g.P_ADJN = false;
          return true;
        } else {
          await TOO_DARK();
        }
      }
      g.P_NAM = false;
      g.P_ADJ = false;
      return false;
    } else if (len == 0) {
      gcheck = true;
      continue loop1;
    }
    x = get(tbl, tlen + 1);
    if (g.P_ADJ && !g.P_NAM && x) {
      tell(S(g.I_ASSUME), " ");
      await ARTICLE(x, true);
      tell(D(x), ".)\n");
    }
    g.P_SLOCBITS = xbits;
    g.P_NAM = false;
    g.P_ADJ = false;
    return true;
  }
}

