async function PICK_ONE(frob, this_ = false) {
  let l = 0, cnt = 0, rnd = 0, msg = 0, rfrob = 0;
  l = get(frob, 0);
  cnt = get(frob, 1);
  l = l - 1;
  frob = frob + 2;
  rfrob = frob + (cnt * 2);
  if (this_ && (cnt == 0)) {
    rnd = this_;
  } else {
    rnd = random(l - cnt);
  }
  msg = get(rfrob, rnd);
  put(rfrob, rnd, get(rfrob, 1));
  put(rfrob, 1, msg);
  cnt = cnt + 1;
  if (cnt == l) {
    cnt = 0;
  }
  put(frob, 0, cnt);
  return msg;
}

