async function I_BOOT_PATROL() {
  let dir_index = 0, dir_table = 0, place = 0, where_boots = 0;
  if (g.ECLIPSE$) {
    return true;
  }
  if (g.LAST_PLACE == g.HERE) {
    where_boots = loc(BOOTS);
    if (g.FUZZY$ && (g.FUZZY_FROM == where_boots)) {
      tell("\nThe fuzzy");
      await TRAMP();
      tell("fades away.\n");
    }
    g.BOOT_LOC = g.BOOT_LOC + 1;
    if (g.BOOT_LOC > BOOT_MAX) {
      g.BOOT_LOC = 0;
    }
    where_boots = get(g.BOOT_PATH, g.BOOT_LOC);
    move(BOOTS, where_boots);
  } else {
    where_boots = loc(BOOTS);
    g.LAST_PLACE = g.HERE;
  }
  if (g.FUZZY$ && (g.FUZZY_FROM == where_boots)) {
    tell("\n", S(g.YOU_HEAR), "the");
    await TRAMP();
    tell("all around you. But the sound is fuzzy and oddly distant.\n");
    return true;
  }
  if (g.HERE == where_boots) {
    await DEPOSIT_BRANCH();
    tell("\nThe night is filled with rhythmic thunder, and a platoon of gigantic leather army ", D(BOOTS), " marches into view. It's the Boot Patrol");
    if (!(g.JAIL_VISITS == 0)) {
      tell(" again");
    }
    tell("!\n\nYou're immediately surrounded, tied, gagged and dragged before an especially tall Boot. ");
    if (g.JAIL_VISITS == 0) {
      tell("\"What have we here?\" he hisses. \"Out after curfew? Tsk, tsk, tsk. I wonder what ", D(MACGUFFIN), " will say about this.\"");
    } else if (g.JAIL_VISITS == 1) {
      tell("\"What!\" he cries. \"I thought you were locked up with ", D(MACGUFFIN), ". Tsk, tsk.\"");
    } else {
      tell("\"Escaped again!\" He looks around at the silent platoon. \"We don't want to bother ", D(MACGUFFIN));
      await SHARK_SNACK();
    }
    await THROWN_OVER_SHOULDER();
    if (g.JAIL_VISITS == 0 || g.JAIL_VISITS == 1) {
      tell("the ", D(GLOBBY), " of the ", D(INSIDE_POLICE_STATION), ".\n\n", D(MACGUFFIN), " glares at you as the ", D(BOOTS), " dump you on the floor. ");
      if (g.JAIL_VISITS == 0) {
        tell("\"What's this?\" he demands impatiently.\n\n\"A nightcrawler,\" hisses the Tall Boot, giving you a vicious little kick. \"Outside after curfew. Shall I feed it to the ", D(SHARKS), "?\"\n\n", D(MACGUFFIN), " shakes his head. \"Later. The Tower wants all prisoners held for questioning.\" He turns back to his work. \"Cell Three.\"");
      } else {
        tell("His eyes narrow when he sees you. ");
        await JAIL_AGAIN();
      }
      await TO_JAIL();
    } else {
      await INTO_BAY();
    }
    return true;
  }
  dir_index = 0;
  dir_table = get(g.DIRECTION_TABLES, g.BOOT_LOC);
  for (;;) {
    if (dir_index > DIR_MAX) {
      return true;
    }
    place = get(dir_table, dir_index);
    if (place == PARK) {
      if ((dir_index == 0 || dir_index == 1) && (g.HERE == ROTARY_WEST || g.HERE == ROTARY_EAST)) {
        place = g.HERE;
      } else if ((dir_index == 2 || dir_index == 3) && (g.HERE == ROTARY_NORTH || g.HERE == ROTARY_SOUTH)) {
        place = g.HERE;
      }
    }
    if (g.HERE == place) {
      await THIS_IS_IT(BOOTS);
      tell("\n", S(g.YOU_HEAR), "the");
      await TRAMP();
      tell(S(get(g.DIR_NAMES, dir_index)), ".");
      if (g.HERE == get(g.BOOT_PATH, g.BOOT_LOC + 1)) {
        await COMING_THIS_WAY();
      }
      crlf();
      return true;
    }
    dir_index = dir_index + 1;
  }
}

