async function V_TIME() {
  let h = 0, m = 0;
  tell("(It's ");
  await TELL_TIME();
  if (hasFlag(ENVELOPE, TOUCHBIT) && !(g.HERE == INSIDE_SHOPPE) && !g.ENDING$) {
    tell(". You have ");
    if (g.SKEWED$) {
      if (g.SCORE > 17) {
        h = (24 - g.SCORE) + 5;
      } else {
        h = 5 - g.SCORE;
      }
    } else {
      h = 16 - g.SCORE;
    }
    if (g.MOVES == 0) {
      m = 0;
      h = h + 1;
    } else {
      m = 60 - g.MOVES;
    }
    if (h == 0) {
      tell("only ");
    } else {
      tell(N(h), " hour");
      if (!(h == 1)) {
        tell("s");
      }
      tell(" ");
      if (!(m == 0)) {
        tell("and ");
      }
    }
    if (!(m == 0)) {
      tell(N(m), " minute");
      if (!(m == 1)) {
        tell("s");
      }
      tell(" ");
    }
    tell("to complete your ");
    if (g.SKEWED$) {
      tell("quest");
    } else {
      tell("delivery");
    }
  }
  tell(".)\n");
  return true;
}

async function TELL_TIME() {
  let h = 0, pm$ = false;
  if (g.SCORE > 11) {
    pm$ = true;
  }
  if (g.SCORE > 12) {
    h = g.SCORE - 12;
  } else if (g.SCORE == 0) {
    h = 12;
  } else {
    h = g.SCORE;
  }
  tell(N(h), ":");
  if (g.MOVES < 10) {
    tell("0");
  }
  tell(N(g.MOVES));
  if (pm$) {
    tell(" pm");
    return true;
  } else {
    tell(" am");
    return true;
  }
}

