async function V_CLOSE() {
  if (hasFlag(g.PRSO, ACTORBIT)) {
    return (await NOT_A("surgeon"));
  } else if (hasFlag(g.PRSO, SURFACEBIT)) {
    return await CANT_CLOSE_THAT();
  } else if (!(hasFlag(g.PRSO, CONTBIT)) && !(hasFlag(g.PRSO, DOORBIT))) {
    await PERFORM(V.OPEN, g.PRSO);
    return true;
  } else if (!(hasFlag(g.PRSO, SURFACEBIT)) && !(eq(getProp(g.PRSO, P.CAPACITY), 0))) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      await NOW_CLOSED_OR_OPEN(g.PRSO);
      return await SAY_IF_NOT_LIT();
    } else {
      return await ALREADY_CLOSED();
    }
  } else if (hasFlag(g.PRSO, DOORBIT)) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      await NOW_CLOSED_OR_OPEN(g.PRSO);
      if (g.PRSO == LIBRARY_DOOR) {
        clearFlag(CIRCULATION_DESK, ONBIT);
        return await SAY_IF_NOT_LIT();
      } else {
        return false;
      }
    } else {
      return await ALREADY_CLOSED();
    }
  } else {
    return await CANT_CLOSE_THAT();
  }
}

