async function NOW_CLOSED_OR_OPEN(thing, open$ = false) {
  await THIS_IS_IT(thing);
  tell(S(g.OKAY));
  await ARTICLE(g.PRSO, true);
  tell(D(g.PRSO), " is now ");
  if (open$) {
    setFlag(thing, OPENBIT);
    tell("open");
  } else {
    clearFlag(thing, OPENBIT);
    tell("closed");
  }
  tell(".\n");
  return true;
}

