async function CCOUNT(thing) {
  let obj = 0, cnt = 0;
  obj = first(thing);
  loop1: for (;;) {
    if (obj) {
      if (!(hasFlag(obj, WORNBIT))) {
        cnt = cnt + 1;
      }
      obj = next(obj);
    } else {
      break loop1;
    }
  }
  return cnt;
}

async function WEIGHT(thing) {
  let obj = 0, wt = 0;
  obj = first(thing);
  loop1: for (;;) {
    if (obj) {
      if ((thing == PROTAGONIST) && hasFlag(obj, WORNBIT)) {
        wt = wt + 1;
      } else {
        wt = wt + (await WEIGHT(obj));
      }
      obj = next(obj);
    } else {
      break loop1;
    }
  }
  wt = wt + getProp(thing, P.SIZE);
  return wt;
}

