async function CANINE_F(context = false) {
  if (isVerb(V.EXAMINE)) {
    await SAY_THE(g.POOCH);
    tell(" is ");
    if (g.ECLIPSE$) {
      tell("watching the dark sky anxiously");
    } else if (g.HELLHOUND_HAPPY$) {
      tell("thumping its big tail happily");
    } else if (g.SKEWED$) {
      tell("big enough to eat you whole, and willing to try");
    } else if (g.POODLE_HAPPY$) {
      tell("watching you as it gnaws on the bone");
    } else {
      tell("tiny, mean and ");
      if (hasFlag(POODLE, RMUNGBIT)) {
        tell("hungry");
      } else {
        tell("nasty");
      }
      tell("-looking");
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.TAKE) && (g.PRSO == g.POOCH)) {
    await SAY_THE(g.POOCH);
    await MIGHT_NOT_LIKE();
    return true;
  } else if (isVerb(V.RUB, V.KISS)) {
    await SAY_THE(g.POOCH);
    if (g.HELLHOUND_HAPPY$) {
      tell(" seems to enjoy your attention.\n");
    } else {
      tell(" would probably chew you up");
      await IF_YOU_TRIED();
    }
    return true;
  } else if (isVerb(V.GIVE, V.THROW, V.FEED) && (g.PRSI == g.POOCH || g.PRSI == ALEXIS)) {
    if (g.PRSO == BROOM) {
      await GET_OFF_BROOM_FIRST();
    }
    await SAY_THE(g.POOCH);
    if (g.ECLIPSE$) {
      tell(" is too uneasy to notice it.\n");
      return true;
    }
    tell(" tests ");
    await ARTICLE(g.PRSO, true);
    tell(D(g.PRSO), " with its tongue, ");
    if (g.PRSO == BONE) {
      move(BONE, OUTSIDE_COTTAGE);
      setFlag(BONE, NDESCBIT);
      clearFlag(POODLE, RMUNGBIT);
      g.POODLE_HAPPY$ = true;
      tell("lies down and begins to gnaw on it, keeping a red eye on you.\n\n");
      await UPDATE_SCORE(3);
      return true;
    } else if (g.PRSO == CHOCOLATE || g.PRSO == WORM) {
      remove(g.PRSO);
      tell("gobbles it down greedily");
    } else {
      move(g.PRSO, OUTSIDE_COTTAGE);
      tell("drops it on the road");
    }
    tell(" and turns to ");
    await BARK_OR_ROAR();
    tell(" at you again.\n");
    return true;
  } else if ((await TALKING_TO$(g.POOCH)) || (await TALKING_TO$(ALEXIS)) || (g.PRSA == V.YELL)) {
    if (g.HELLHOUND_HAPPY$) {
      await SOUND_OF_VOICE();
      return M_FATAL;
    }
    await SAY_THE(g.POOCH);
    tell(" growls ");
    if (g.ECLIPSE$) {
      tell("uneasi");
    } else {
      tell("dangerous");
    }
    tell("ly in reply.\n");
    return M_FATAL;
  } else if ((await HURT$(g.POOCH)) || isVerb(V.CLIMB_ON, V.CLIMB_UP, V.SHAKE, V.SQUEEZE)) {
    if (g.HELLHOUND_HAPPY$) {
      tell("Why");
      await DO_TO();
      tell("a friendly, obedient ", D(HELLHOUND), "?");
    } else {
      tell("Are you kidding? This ", D(g.POOCH), " is MEAN!");
    }
    crlf();
    return true;
  } else if (isVerb(V.LISTEN)) {
    tell("It ");
    await BARK_OR_ROAR();
    tell("s louder.\n");
    return true;
  } else {
    return false;
  }
}

