async function I_BARKING() {
  let $1;
  if (g.FUZZY$ || g.ECLIPSE$) {
    return true;
  } else if (g.HERE == OUTSIDE_COTTAGE) {
    if (g.POODLE_HAPPY$) {
      return true;
    }
    g.DOG_SCRIPT = g.DOG_SCRIPT + 1;
    g.P_HINT = g.P_HINT + 1;
    await THIS_IS_IT(g.POOCH);
    crlf();
    if (!g.SKEWED$ && hasFlag(POODLE, RMUNGBIT) && !(loc(BONE) == PROTAGONIST) && (g.P_HINT > 8)) {
      g.DOG_SCRIPT = 0;
      g.P_HINT = 0;
      tell("(");
      $1 = await PICK_ONE(g.POODLE_HINTS);
      tell(S($1));
      tell(".)\n");
      return true;
    } else if (g.DOG_SCRIPT == 1) {
      tell("You can smell the ", D(g.POOCH), "'s hot breath as it ");
      await BARK_OR_ROAR();
      tell("s.\n");
      return true;
    } else if (g.DOG_SCRIPT == 2) {
      await SAY_THE(g.POOCH);
      tell(" glares at you through eyes red with hatred.\n");
      return true;
    } else if (g.DOG_SCRIPT == 3) {
      tell(S(g.YOU_HEAR), "the ", D(g.POOCH), "'s ");
      await TEETH_OR_FANGS();
      tell(" snapping as it nips your heels.\n");
      return true;
    } else if (g.DOG_SCRIPT == 4) {
      await SAY_THE(g.POOCH);
      tell(" circles you warily, snarling and growling with menace.");
      if (g.SKEWED$ && !g.LUCKY$) {
        tell(" It looks as if it's getting ready to attack!");
      } else {
        g.DOG_SCRIPT = 0;
      }
      return crlf();
    } else {
      tell("With a savage leap, the ", D(HELLHOUND), " lives up to its bloodthirsty reputation.");
      return await BAD_ENDING();
    }
  } else {
    return false;
  }
}

